import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const fetchCursos = async () => {
    try {
      setLoading(true);
      setError(null);

      const resposta = await private_api.get("/professor/cursos");

      if (resposta.status === 200) {
        setCursos(resposta.data);
      } else {
        setError("Erro ao carregar cursos");
        console.error("Erro ao buscar cursos:", resposta.statusText);
      }
    } catch (error) {
      setError("Erro na conexão com o servidor");
      console.error("Erro na requisição:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCursos();
  }, []);

  const handleRefresh = () => {
    fetchCursos();
  };

  if (loading) {
    return (
      <div
        className="d-flex justify-content-center align-items-center"
        style={{ minHeight: "100vh" }}
      >
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mt-5 text-center">
        <div className="alert alert-danger">
          {error}
          <button className="btn btn-link" onClick={handleRefresh}>
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center rounded">
        <button
          className="nav-link active"
          onClick={() => window.location.reload()} // Recarrega a página de cursos
        >
          Cursos
        </button>
        <button
          className="nav-link"
          onClick={() => navigate("/professoraulas")}
        >
          Aulas
        </button>
        <button
          className="nav-link"
          onClick={() => navigate("/professoravaliacoes")}
        >
          Avaliações
        </button>
      </nav>

      <div className="d-flex justify-content-between align-items-center w-75 mb-4">
        <h2 className="mb-0">Lista de Cursos à lecionar</h2>
        <button className="btn btn-primary" onClick={handleRefresh}>
          <i className="fas fa-sync-alt"></i> Atualizar
        </button>
      </div>

      <div className="w-75 bg-white rounded shadow p-3">
        {cursos.length > 0 ? (
          <table className="table table-hover">
            <thead className="table-light">
              <tr>
                <th>Curso</th>
                <th>Nível</th>
                <th>Data de Início</th>
                <th>Data de Fim</th>
                
              </tr>
            </thead>
            <tbody>
              {cursos.map((curso) => (
                <tr
                  key={curso.id}
                  style={{ cursor: "pointer" }}
                  onClick={() => navigate(`/curso/${curso.id}`)}
                >
                  <td>{curso.nome}</td>
                  <td>{curso.nivel}</td>
                  <td>
                    {new Date(curso.dataInicio).toLocaleDateString("pt-PT")}
                  </td>
                  <td>{new Date(curso.dataFim).toLocaleDateString("pt-PT")}</td>
                  <td>{curso.periodo}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <div className="text-center py-5">
            <h4>Nenhum curso encontrado</h4>
            <p>Você não está atribuído a nenhum curso no momento.</p>
            <button className="btn btn-primary" onClick={handleRefresh}>
              Verificar novamente
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default LecionaLista;
